lay(5000);  // 5 seconds\n}\n\nfloat readBatteryVoltage() {\n  // Enable ADC\n  digitalWrite(ADC_EN_PIN, HIGH);\n  delay(10);  // Short delay to stabilize\n\n  // Read 30 times and average for more stable readings\n  long sum = 0;\n  for(int i = 0; i < 30; i++) {\n    sum += analogRead(BATTERY_PIN);\n    delayMicroseconds(100);\n  }\n\n  // Disable ADC to save power\n  digitalWrite(ADC_EN_PIN, LOW);\n\n  // Calculate voltage\n  float adc_avg = sum / 30.0;\n  float voltage = (adc_avg / 4095.0) * 3.6 * 2.0 * CALIBRATION_FACTOR;\n\n  return voltage;\n}\n'})}),"\n",(0,r.jsx)(e.p,{children:(0,r.jsx)(e.strong,{children:"\u4EE3\u7801\u5DE5\u4F5C\u539F\u7406\uFF1A"})}),"\n",(0,r.jsxs)(e.ol,{children:["\n",(0,r.jsx)(e.li,{children:"\u6211\u4EEC\u5B9A\u4E49\u4E86\u4E24\u4E2A\u91CD\u8981\u7684\u5F15\u811A\uFF1A"}),"\n"]}),"\n",(0,r.jsxs)(e.ul,{children:["\n",(0,r.jsxs)(e.li,{children:["\n",(0,r.jsxs)(e.p,{children:[(0,r.jsx)(e.code,{children:"BATTERY_PIN"})," (GPIO1/A0)\uFF1A\u8FDE\u63A5\u5230\u7535\u6C60\u5206\u538B\u7535\u8DEF"]}),"\n"]}),"\n",(0,r.jsxs)(e.li,{children:["\n",(0,r.jsxs)(e.p,{children:[(0,r.jsx)(e.code,{children:"ADC_EN_PIN"})," (GPIO6/A5)\uFF1A\u7528\u4E8E\u63A7\u5236 ADC \u6D4B\u91CF\u7535\u8DEF\u7684\u4F9B\u7535"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(e.ol,{start:"2",children:["\n",(0,r.jsxs)(e.li,{children:["\n",(0,r.jsxs)(e.p,{children:["\u6211\u4EEC\u5B9A\u4E49\u4E86\u4E00\u4E2A ",(0,r.jsx)(e.code,{children:"CALIBRATION_FACTOR"})," (0.968) \u6765\u5FAE\u8C03\u7535\u538B\u8BFB\u6570\u7684\u7CBE\u5EA6\u3002"]}),"\n"]}),"\n",(0,r.jsxs)(e.li,{children:["\n",(0,r.jsxs)(e.p,{children:["\u5728 ",(0,r.jsx)(e.code,{children:"setup()"})," \u51FD\u6570\u4E2D\uFF1A"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(e.ul,{children:["\n",(0,r.jsxs)(e.li,{children:["\n",(0,r.jsx)(e.p,{children:"\u521D\u59CB\u5316\u4E32\u53E3\u901A\u4FE1"}),"\n"]}),"\n",(0,r.jsxs)(e.li,{children:["\n",(0,r.jsx)(e.p,{children:"\u5C06 ADC_EN \u5F15\u811A\u914D\u7F6E\u4E3A\u8F93\u51FA\u5E76\u8BBE\u7F6E\u4E3A